C.petTabs = {409,410,411}
C.spellSet = {}
for classId, specs in pairs(C.spells) do
  for specId, ids in pairs(specs) do
    local kept = {}
    for i = 1, #ids do
      local sid = ids[i]
      if not (C.blockedSpells and C.blockedSpells[sid]) then
        kept[#kept + 1] = sid
        C.spellSet[sid] = true
      end
    end
    C.spells[classId][specId] = kept
  end
end
do
  local kept = {}
  for i = 1, #(C.generalSpells or {}) do
    local sid = C.generalSpells[i]
    if not (C.blockedSpells and C.blockedSpells[sid]) then
      kept[#kept + 1] = sid
      C.spellSet[sid] = true
    end
  end
  C.generalSpells = kept
  C.generalSet = {}
  for i = 1, #kept do C.generalSet[kept[i]] = true end
end
do
  local kept = {}
  for i = 1, #(C.petSpells or {}) do
    local sid = C.petSpells[i]
    if not (C.blockedSpells and C.blockedSpells[sid]) then
      kept[#kept + 1] = sid
      C.spellSet[sid] = true
    end
  end
  C.petSpells = kept
end
C.talentById = {}
for tabId, nodes in pairs(C.talents) do
  for i = 1, #nodes do
    local n = nodes[i]
    n.tabId = tabId
    C.talentById[n.id] = n
  end
end

local AIO = AIO or require("AIO")
if AIO.IsMainState and AIO.IsMainState() and AIO.AddAddon then
  AIO.AddAddon()
end

